INSERT INTO `command` VALUES
(35,NULL,'host-notify-by-email','/usr/bin/printf &quot;%b&quot; &quot;***** centreon Notification *****#BR##BR#Type:$NOTIFICATIONTYPE$#BR#Host: $HOSTNAME$#BR#State: $HOSTSTATE$#BR#Address: $HOSTADDRESS$#BR#Info: $HOSTOUTPUT$#BR#Date/Time: $DATE$&quot; | @MAILER@ -s &quot;Host $HOSTSTATE$ alert for $HOSTNAME$!&quot; $CONTACTEMAIL$','',1,1,NULL,'1',NULL,NULL,0),
(36,NULL,'service-notify-by-email','/usr/bin/printf &quot;%b&quot; &quot;***** centreon Notification *****#BR##BR#Notification Type: $NOTIFICATIONTYPE$#BR##BR#Service: $SERVICEDESC$#BR#Host: $HOSTALIAS$#BR#Address: $HOSTADDRESS$#BR#State: $SERVICESTATE$#BR##BR#Date/Time: $DATE$ Additional Info : $SERVICEOUTPUT$&quot; | @MAILER@ -s &quot;** $NOTIFICATIONTYPE$ alert - $HOSTALIAS$/$SERVICEDESC$ is $SERVICESTATE$ **&quot; $CONTACTEMAIL$','',1,1,NULL,'1',NULL,NULL,0),
(37,NULL,'host-notify-by-epager','/usr/bin/printf &quot;%b&quot; &quot;Host $HOSTALIAS$ is $HOSTSTATE$#BR#Info: $OUTPUT$#BR#Time: $DATETIME$\\&quot; | @MAILER@ -s \\&quot;$NOTIFICATIONTYPE$ alert - Host $HOSTNAME$ is $HOSTSTATE$\\&quot; $CONTACTPAGER$','',1,1,NULL,'1',NULL,NULL,0),
(38,NULL,'service-notify-by-epager','/usr/bin/printf &quot;%b&quot; &quot;Service: $SERVICEDESC$#BR#Host: $HOSTNAME$#BR#Address: $HOSTADDRESS$#BR#State: $SERVICESTATE$#BR#Info: $OUTPUT$#BR#Date: $DATETIME$&quot; | @MAILER@ -s &quot;$NOTIFICATIONTYPE$: $HOSTALIAS$/$SERVICEDESC$ is $SERVICESTATE$&quot; $CONTACTPAGER$','',1,1,NULL,'1',NULL,NULL,0),
(89,NULL,'host-notify-by-jabber','$USER1$/notify_via_jabber  $CONTACTPAGER$ &quot;Host &#039;$HOSTALIAS$&#039; is $HOSTSTATE$ - Info: $HOSTOUTPUT$&quot;','',1,0,NULL,'1',0,NULL,0),
(90,NULL,'service-notify-by-jabber','$USER1$/notify_via_jabber $CONTACTPAGER$ &quot;$NOTIFICATIONTYPE$ $HOSTNAME$ $SERVICEDESC$ $SERVICESTATE$ $SERVICEOUTPUT$ $LONGDATETIME$&quot;','',1,0,NULL,'1',0,NULL,0),
(91,NULL,'base_host_alive','$USER1$/check_icmp -H $HOSTADDRESS$ -w 3000.0,80% -c 5000.0,100% -p 1 -b 52',NULL,2,0,NULL,'1',NULL,NULL,1),
(92,NULL,'App-Monitoring-Centreon-Host-Dummy','$CENTREONPLUGINS$/centreon_centreon_poller.pl --plugin=apps::centreon::local::plugin --mode=dummy --status=\'$_HOSTDUMMYSTATUS$\' --output=\'$_HOSTDUMMYOUTPUT$\'',NULL,2,0,NULL,'1',NULL,NULL,1),
(93,NULL,'base_centreon_ping','$USER1$/check_icmp -H $HOSTADDRESS$ -n $_SERVICEPACKETNUMBER$ -w $_SERVICEWARNING$ -c $_SERVICECRITICAL$ -b $_SERVICEPACKET_SIZE$  $_SERVICEEXTRAOPTIONS$',NULL,2,0,NULL,'1',NULL,NULL,1),
(94,NULL,'App-Monitoring-Centreon-Service-Dummy','$CENTREONPLUGINS$/centreon_centreon_poller.pl --plugin=apps::centreon::local::plugin --mode=dummy --status=\'$_SERVICEDUMMYSTATUS$\' --output=\'$_SERVICEDUMMYOUTPUT$\'',NULL,2,0,NULL,'1',NULL,NULL,1),
(95,NULL,'OS-Linux-SNMP-Storages-Macro','$CENTREONPLUGINS$/centreon_linux_snmp.pl --plugin=os::linux::snmp::plugin --mode=list-storages --hostname=127.0.0.1 --disco-format',NULL,4,0,NULL,'1',NULL,NULL,1),
(96,NULL,'OS-Linux-SNMP-Storages-Discover','$CENTREONPLUGINS$/centreon_linux_snmp.pl --plugin=os::linux::snmp::plugin --mode=list-storages --hostname=$HOSTADDRESS$ --snmp-version=\'$_HOSTSNMPVERSION$\' --snmp-community=\'$_HOSTSNMPCOMMUNITY$\' --snmp-username=\'$_HOSTSNMP_V3_USERNAME$\' --authpassphrase=\'$_HOSTSNMP_V3_AUTH_PASSPHRASE$\' --authprotocol=\'$_HOSTSNMP_V3_AUTH_PROTOCOL$\' --privpassphrase=\'$_HOSTSNMP_V3_PRIV_PASSPHRASE$\' --privprotocol=\'$_HOSTSNMP_V3_PRIV_PROTOCOL$\' $_HOSTSNMPEXTRAOPTIONS$ --disco-show',NULL,4,0,NULL,'1',NULL,NULL,1),
