(98,NULL,'OS-Linux-SNMP-Interfaces-Discover','$CENTREONPLUGINS$/centreon_linux_snmp.pl --plugin=os::linux::snmp::plugin --mode=list-interfaces --hostname=$HOSTADDRESS$ --snmp-version=\'$_HOSTSNMPVERSION$\' --snmp-community=\'$_HOSTSNMPCOMMUNITY$\' --snmp-username=\'$_HOSTSNMP_V3_USERNAME$\' --authpassphrase=\'$_HOSTSNMP_V3_AUTH_PASSPHRASE$\' --authprotocol=\'$_HOSTSNMP_V3_AUTH_PROTOCOL$\' --privpassphrase=\'$_HOSTSNMP_V3_PRIV_PASSPHRASE$\' --privprotocol=\'$_HOSTSNMP_V3_PRIV_PROTOCOL$\' $_HOSTSNMPEXTRAOPTIONS$ --disco-show',NULL,4,0,NULL,'1',NULL,NULL,1),
